import{_ as l,a8 as r,o as d,c as p,au as i,a as g,a3 as o,K as e,L as h}from"./chunks/framework.C98eyFBZ.js";import"./chunks/theme.C2tOVGE8.js";const N=JSON.parse('{"title":"知识库批量改动前要做的第一件事","description":"","frontmatter":{"title":"知识库批量改动前要做的第一件事","abstract":"批量改笔记之前不先留快照，等于没有回退基线。而快照本身也有失效方式——跳过文件太多、退出码异常、副本不完整。这篇文章给出一套能核对的开工流程，以及它为什么必须由人确认。","created":"2026-11-10T00:00:00.000Z","updated":"2026-11-10T00:00:00.000Z","type":"教程","tags":["知识管理","备份","数据安全"],"category":["📚 个人知识管理","知识库运维"]},"headers":[],"relativePath":"vault/Knowledge/Methods/知识库批量改动前要做的第一件事.md","filePath":"vault/Knowledge/Methods/知识库批量改动前要做的第一件事.md","lastUpdated":1794320166000}'),_={name:"vault/Knowledge/Methods/知识库批量改动前要做的第一件事.md"};function b(c,t,m,u,f,P){const a=r("VPNolebaseInlineLinkPreview"),n=r("NolebaseGitContributors"),s=r("NolebaseGitChangelog");return d(),p("div",null,[t[3]||(t[3]=i('<h1 id="知识库批量改动前要做的第一件事" tabindex="-1">知识库批量改动前要做的第一件事 <a class="header-anchor" href="#知识库批量改动前要做的第一件事" aria-label="Permalink to “知识库批量改动前要做的第一件事”">​</a></h1><p>改一百篇笔记的 frontmatter、重排整个目录、把所有标题统一格式——这类操作有个共同点：<strong>它们出错的方式是静默的。</strong></p><p>单篇编辑改错了，你立刻看得见。批量操作改错了，你可能三个月后才发现某个目录的笔记全部丢了标签，而此时你已经不知道是哪一次操作干的。</p><p>所以真正的问题不是「要不要备份」，而是<strong>备份到什么程度才算数</strong>。</p><p>答案是：<strong>备份到自己能核对为止。</strong> 拷了一份但不知道它是否完整，那不叫备份，叫心理安慰。</p><h2 id="一、先划范围-什么操作必须留快照" tabindex="-1">一、先划范围：什么操作必须留快照 <a class="header-anchor" href="#一、先划范围-什么操作必须留快照" aria-label="Permalink to “一、先划范围：什么操作必须留快照”">​</a></h2><p>不是所有改动都要。门槛定得太低，你会因为麻烦而每次都不做。</p><p><strong>必须留：</strong></p><ul><li>会写入十个以上文件的操作</li><li>会移动、重命名、删除既有文件的任何操作</li><li>批量修改 frontmatter 的操作</li><li>目录重排、结构迁移、分类体系调整</li><li>规则类文档的批量改写</li></ul><p><strong>不必留：</strong></p><ul><li>单篇笔记的编辑</li><li>新建一篇笔记</li><li>只读审计、体检、生成报告</li></ul><p>分界线不在「改了多少」，在<strong>改错了能不能手动改回来</strong>。能改回来的，不必留；改不回来的，必须留。</p><h2 id="二、开工前的三个前置条件" tabindex="-1">二、开工前的三个前置条件 <a class="header-anchor" href="#二、开工前的三个前置条件" aria-label="Permalink to “二、开工前的三个前置条件”">​</a></h2><p>这三条中任何一条不满足，别开始。</p><p><strong>第一，目标存储空间够用。</strong> 快照的体积大致等于库本身的体积。空间不够时，很多同步工具会中途停下并返回非零退出码——而<strong>中途停下的快照比没有快照更危险</strong>，因为你会以为自己有回退点。</p><p><strong>第二，明确这次要动哪些层。</strong> 只改笔记正文和标签，用一个轻量的部分快照就够；要动附件、归档、资源目录，就必须是全量。用错档位的后果是：回退时发现被误删的那批文件恰好不在快照里。</p><p><strong>第三，确认源库正在被程序占用的情况。</strong> 笔记软件通常会在运行，某些目录（缓存、日志、临时会话）在被锁定时同步会跳过。这些跳过是正常的，但你<strong>必须知道跳过了哪些</strong>，否则你把「被跳过」当成了「已备份」。</p><h2 id="三、固定动作-五步-一步都不能省" tabindex="-1">三、固定动作：五步，一步都不能省 <a class="header-anchor" href="#三、固定动作-五步-一步都不能省" aria-label="Permalink to “三、固定动作：五步，一步都不能省”">​</a></h2><blockquote><p>跳过任何一步，都视为没有执行。</p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>动作</th><th>检查点</th></tr></thead><tbody><tr><td>1</td><td>跑一次快照，带阶段名标记</td><td>退出码落在正常区间，状态不是失败</td></tr><tr><td>2</td><td>打开这次快照的清单文件</td><td>源文件数与副本文件数的差值，能被跳过原因完整解释</td></tr><tr><td>3</td><td>抽查三到五个即将被改的文件，比对源与副本的哈希</td><td>全部一致</td></tr><tr><td>4</td><td>把快照目录名写进本次任务的记录里</td><td>能用一句话唯一定位到那个目录</td></tr><tr><td>5</td><td>这时才开始批量写入</td><td>写入过程中的临时备份与快照同时存在</td></tr></tbody></table><p>第 2 步和第 3 步是大多数人省掉的，而它们正是「备份」变成「可核对的备份」的地方。</p><p><strong>清单文件的价值在于它解释了缺口。</strong> 源有 39,000 个文件、副本有 38,996 个，这个差值如果不解释，你就不知道丢的是垃圾文件还是你的笔记。合格的清单会列出每一个被跳过的路径和原因。</p><p><strong>哈希抽查的价值在于它验证了内容，而不只是数量。</strong> 数量对得上可能只是同名文件被覆盖。抽几份马上要改的文件，比对源和副本的哈希，这是唯一能证明「副本确实是那一刻的内容」的动作。</p><h2 id="四、验收门槛-什么叫做完了" tabindex="-1">四、验收门槛：什么叫做完了 <a class="header-anchor" href="#四、验收门槛-什么叫做完了" aria-label="Permalink to “四、验收门槛：什么叫做完了”">​</a></h2><p>三条件全部满足，才算这一次快照可用：</p><ol><li><strong>清单文件存在</strong>，且状态是「完整」或「完整但个别文件被占用」。</li><li><strong>抽查文件哈希全部一致。</strong></li><li><strong>被跳过的项只有已知的那几类</strong>，且每一类都能在清单里找到理由。</li></ol><p>第三条最容易被放过。常见的合理跳过大概是这几种：被程序锁住的日志、临时会话视图、权限受限的构建产物、备份目录自身的嵌套。</p><p><strong>出现第五类跳过项时，视为未通过。</strong> 先解释它从哪来，再继续。你不能对未知的缺口说「应该没事」。</p><h2 id="五、失败之后怎么办" tabindex="-1">五、失败之后怎么办 <a class="header-anchor" href="#五、失败之后怎么办" aria-label="Permalink to “五、失败之后怎么办”">​</a></h2><p>这部分比开工流程更重要，因为这里全是不该做的事。</p><p><strong>没做快照就开始批量写入</strong>——立即停下。不要用「反正改动很小」自我豁免，这个念头本身就是事故的开头。正确顺序是：先按当前状态补一次快照，然后从写入工具的临时备份里逐文件回退。</p><p><strong>退出码异常</strong>——快照不完整，视为没做。删掉这个残缺的目录重跑一次，<strong>不要在残缺快照上继续</strong>，因为它会给你一种「有退路」的错觉。</p><p><strong>恢复的时候</strong>——方向只有一条：从快照往源库灌。且必须满足三个条件：人工确认目标、先保留当前版本、按子树恢复而不是整库覆盖。</p><p>最后这条特别重要：<strong>不要写脚本自动反向同步。</strong> 双向同步的逻辑一旦出错，会把快照也污染掉，那时你就同时失去了现状和退路。</p><p><strong>发现空间不够时</strong>——停下来，去清空间或换盘。不要退而求其次改成「只备份将要改的那几个文件」。那样做会丢掉「当时整库长什么样」这个信息，而批量操作出问题时，你恰恰最需要知道整库原貌。</p><h2 id="六、为什么这套流程必须由人确认" tabindex="-1">六、为什么这套流程必须由人确认 <a class="header-anchor" href="#六、为什么这套流程必须由人确认" aria-label="Permalink to “六、为什么这套流程必须由人确认”">​</a></h2><p>每一步都可以自动化，但有一个判断无法自动化：<strong>这次改动值不值得冒险。</strong></p><p>工具能告诉你快照完整、哈希一致、跳过项合理。它不能告诉你「为了把标签格式统一，动三千篇笔记是否划算」。这个判断只能人来做，而它的质量决定了整套流程是保护还是仪式。</p><p>所以流程设计的重点不是让它跑得更快，是让它<strong>在关键节点强制停下来让人看一眼</strong>。第 2 步看清单、第 3 步验哈希、第 5 步才开始写——三个停顿点，每个都在问同一个问题：<strong>你现在确定可以往下走吗？</strong></p><p>批量操作真正的成本不是执行时间，是「发现错了」到「确认改回来」之间的那段时间。快照买的就是那段时间。</p><hr>',41)),g("p",null,[t[1]||(t[1]=o("关于「改什么」的判断，见 ",-1)),e(a,{href:"/nebula-blog/vault/Knowledge/Methods/七种笔记法其实是一套流水线的七个工位.html"},{default:h(()=>[...t[0]||(t[0]=[o("七种笔记法其实是一套流水线的七个工位",-1)])]),_:1}),t[2]||(t[2]=o("——那篇讲内容怎么流转，这篇讲结构变动前的保险丝。",-1))]),e(n),e(s)])}const v=l(_,[["render",b]]);export{N as __pageData,v as default};
